+            <D:name>calendar-query</D:name>
+          </D:report>
+          <D:report>
+            <D:name>calendar-multiget</D:name>
+          </D:report>
+          <D:report>
+            <D:name>sync-collection</D:name>
+          </D:report>
+        </D:supported-report-set>
+{privilege_set}{owner_block}
+      </D:prop>
+      <D:status>HTTP/1.1 200 OK</D:status>
+    </D:propstat>
+  </D:response>"#
+    )
+}
