        &self,
        actor_user_id: i64,
        is_superadmin: bool,
        calendar_id: i64,
        series_id: i64,
        recurrence_id: i64,
        expected_version: i64,
    ) -> Result<EventProjection, EventServiceError> {
        let now = (self.clock)();
        let mut transaction = self.pool.begin_with("BEGIN IMMEDIATE").await?;
        authorize_in_transaction(
            &mut transaction,
            actor_user_id,
            is_superadmin,
