use commoncal_backend::caldav::ical::{CaldavIcalEvent, serialize_event_resource};
use commoncal_backend::ics::{IcsParserLimits, parse_calendar};

#[test]
fn dst_ambiguity_check() {
    // 2026-11-01 is the DST fallback day for America/New_York (2:00 AM EDT -> 1:00 AM EST)
    // Event A: 06:30 UTC = 1:30 AM EDT (first occurrence)
    // Event B: 07:30 UTC = 1:30 AM EST (second occurrence)
    let event_a = CaldavIcalEvent {
        uid: "event-a".to_owned(),
        summary: "A".to_owned(),
        description: None,
        location: None,
        status: Some("CONFIRMED".to_owned()),
        start_utc: chrono::Utc.with_ymd_and_hms(2026, 11, 1, 6, 30, 0).single().unwrap().timestamp(),
        end_utc: chrono::Utc.with_ymd_and_hms(2026, 11, 1, 7, 30, 0).single().unwrap().timestamp(),
        timezone: "America/New_York".to_owned(),
        dtstamp: 1_768_435_200,
        sequence: 1,
    };
    let event_b = CaldavIcalEvent {
        uid: "event-b".to_owned(),
        summary: "B".to_owned(),
        description: None,
        location: None,
        status: Some("CONFIRMED".to_owned()),
        start_utc: chrono::Utc.with_ymd_and_hms(2026, 11, 1, 7, 30, 0).single().unwrap().timestamp(),
        end_utc: chrono::Utc.with_ymd_and_hms(2026, 11, 1, 8, 30, 0).single().unwrap().timestamp(),
        timezone: "America/New_York".to_owned(),
        dtstamp: 1_768_435_200,
        sequence: 1,
    };
    let ics_a = serialize_event_resource(&event_a);
    let ics_b = serialize_event_resource(&event_b);
    eprintln!("ICS A:\n{ics_a}");
    eprintln!("ICS B:\n{ics_b}");
    // Check if the DTSTART lines are the same (lossy serialization)
    let dtstart_a = ics_a.lines().find(|l| l.starts_with("DTSTART")).unwrap();
    let dtstart_b = ics_b.lines().find(|l| l.starts_with("DTSTART")).unwrap();
    eprintln!("DTSTART A: {dtstart_a}");
    eprintln!("DTSTART B: {dtstart_b}");
    eprintln!("Same DTSTART? {}", dtstart_a == dtstart_b);
    // Check if the parser can parse them
    let parsed_a = parse_calendar(&ics_a, IcsParserLimits::default());
    let parsed_b = parse_calendar(&ics_b, IcsParserLimits::default());
    eprintln!("Parse A: {:?}", parsed_a.as_ref().map(|c| c.events.len()));
    eprintln!("Parse B: {:?}", parsed_b.as_ref().map(|c| c.events.len()));
    if let Ok(parsed_a) = &parsed_a {
        if let commoncal_backend::ics::NormalizedTiming::Timed { starts_at, .. } = &parsed_a.events[0].timing {
            eprintln!("Parsed A start: {}", starts_at.format("%Y-%m-%d %H:%M:%S UTC"));
        }
    }
    if let Ok(parsed_b) = &parsed_b {
        if let commoncal_backend::ics::NormalizedTiming::Timed { starts_at, .. } = &parsed_b.events[0].timing {
            eprintln!("Parsed B start: {}", starts_at.format("%Y-%m-%d %H:%M:%S UTC"));
        }
    }
}

